+/**
+ * Sanitize a value for safe embedding into a generated string literal.
+ * Prevents code injection from untrusted OpenAPI spec fields
+ * (e.g. x-enumDescriptions) by escaping characters that have
+ * special meaning in JavaScript/TypeScript string literals.
+ */
+export const sanitize = (value: unknown): string => {
+  if (value === null || value === undefined) {
+    return '';
+  }
+  // JSON.stringify produces a properly-escaped, quoted string literal
+  // that is safe to embed in generated TS/JS code. It handles
+  // backslashes, quotes, newlines, backticks, ${} template sequences,
+  // and unicode characters.
+  return JSON.stringify(String(value)).slice(1, -1);
+};

